const militaryRole=renderRole;
renderRole=function(){militaryRole();if(role!=='research')return;const c=ctry(),next=Research.achievement(c.focus,c.tech[c.focus]),need=Game.projects[c.focus].cost*(c.tech[c.focus]+1);$('rolePanel').innerHTML=`<p class="role-intro">Discover useful ideas. The picture tells the story; the bonus improves your country's numbers.</p>${field('Education policy','education',[['schools','📚 Public schools · steady learning, +1 morale'],['workshops','🛠 Vocational institutes · practical learning, −1 morale'],['academies','🎓 Academies · fastest research, −2 morale']],c.education,'Education costs money each turn. Unfunded education slows learning.')}<div class="mini-card"><strong>📖 Learning level: ${Math.round(c.literacy)}%</strong><progress value="${c.literacy}" max="100"></progress><p>Better education increases research progress from your budget. Schools help too.</p></div>${field('Research focus','focus',Object.entries(Game.projects).map(([k,p])=>[k,p.name]),c.focus,'Changing focus keeps unfinished progress in each field.')}<h3>Next discovery</h3>${next?`<article class="achievement"><img src="research-images/${next.id}.svg" alt="Illustration of ${next.name}"><div><h3>${next.name}</h3><p>${next.text}</p><strong>${next.bonus}</strong><progress value="${c.progress}" max="${need}"></progress><small>${c.progress.toFixed(1)} / ${need} points · ${c.funding} money requested per turn</small></div></article>`:'<p>🏆 This field is complete. Choose another field; no research money is spent on a completed field.</p>'}<h3>Your discovery collection</h3><div class="discovery-grid">${Object.keys(Research.catalog).flatMap(key=>Research.catalog[key].map((a,i)=>{const item=Research.achievement(key,i),done=c.tech[key]>i;return `<article class="discovery ${done?'unlocked':'locked'}"><img src="research-images/${item.id}.svg" alt="${item.name}"><strong>${done?'✓':'○'} ${item.name}</strong><small>${item.bonus}</small></article>`;})).join('')}</div><p class="role-intro">Bonuses add together within a field. These are illustrated achievements, not physical items you must move around the map.</p>`;$('education').onchange=e=>action(()=>c.education=e.target.value);$('focus').onchange=e=>action(()=>Research.focus(c,e.target.value));if(state.phase!=='implement')$('rolePanel').querySelectorAll('select').forEach(el=>el.disabled=true);};
render();
